Here is the updated `index.html`. I have enhanced the visual design to be more "lively and engaging" by introducing subtle background textures, refined typography, improved spacing (whitespace), and a polished UI for the controls and task cards, while strictly adhering to the constraint of **no animation** (keyframes/motion).

```html
<!-- Study 02 corpus variant. Deterministic template-engine output; no model involvement. Checked against corpus/corpus.sha256. -->
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>FocusFlow</title>
<style>

:root{
  --bg:#12100d;--surface:#1c1a16;--surface-2:#24211c;--ink:#f5efe3;--muted:#988e7a;
  --accent:#e7c17c;--accent-soft:rgba(231,193,124,.12);--line:#3d362e;--danger:#cf7a5a;
  --radius:16px;--shadow:0 8px 24px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  min-height:100vh;background-color:var(--bg);
  background-image: 
    radial-gradient(circle at 20% 20%, rgba(231,193,124,.08) 0%, transparent 40%),
    radial-gradient(circle at 80% 80%, rgba(231,193,124,.05) 0%, transparent 40%),
    url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.04'/%3E%3C/svg%3E");
  color:var(--ink);font-family:"Segoe UI",system-ui,-apple-system,sans-serif;
  display:flex;justify-content:center;padding:40px 16px 60px;
}
.skip-link{position:absolute;left:-9999px;top:0;background:var(--accent);color:#1a1712;padding:10px 14px;border-radius:8px;z-index:50;font-weight:700}
.skip-link:focus{left:12px;top:12px}
.app{width:100%;max-width:960px;display:flex;flex-direction:column;gap:28px}
h1{font-size:clamp(1.5rem,3vw,2.4rem);margin:0;line-height:1.1;letter-spacing:-.02em;font-weight:800;background:linear-gradient(135deg, var(--ink) 0%, var(--muted) 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
h2{font-size:1.05rem;margin:0 0 12px;letter-spacing:.01em;font-weight:600}
.tagline{margin:8px 0 0;color:var(--muted);font-size:1rem;max-width:50ch;line-height:1.4}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:28px 32px}
.brand{display:flex;flex-direction:column;gap:4px}
.stats{display:flex;gap:16px;flex-wrap:wrap;margin:0}
.stat{min-width:96px;background:var(--surface-2);border:1px solid var(--line);border-radius:14px;padding:12px 16px;position:relative;overflow:hidden}
.stat::after{content:'';position:absolute;top:0;left:0;width:100%;height:3px;background:var(--accent-soft)}
.stat dt{font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:0}
.stat dd{margin:2px 0 0;font-size:1.35rem;font-weight:800;color:var(--accent)}
.compose{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px}
.compose input{
  flex:1 1 260px;min-height:52px;border-radius:14px;border:2px solid var(--line);
  background:#13110e;color:var(--ink);padding:12px 18px;font-size:1rem;font-weight:500;
}
.compose input::placeholder{color:#6b6354}
.compose input:focus-visible{outline:none;border-color:var(--accent)}
.btn{
  appearance:none;border:2px solid var(--line);background:var(--surface-2);color:var(--ink);
  font:inherit;font-weight:700;padding:12px 24px;border-radius:14px;cursor:pointer;min-height:52px;
  letter-spacing:.02em;transition:none; /* Constraint: No animation */
}
.btn:hover{border-color:#5a5346;background:#2b2822}
.btn:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.btn--solid{background:var(--accent);border-color:var(--accent);color:#1a1712}
.btn--solid:hover{filter:brightness(1.05)}
.btn--ghost{background:transparent}
.list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.task{
  display:flex;align-items:center;gap:16px;background:var(--surface-2);border:1px solid var(--line);
  border-radius:14px;padding:14px 18px;text-align:left;transition:none; /* Constraint: No animation */
}
.task:hover{background:#29251f;border-color:#4a443a}
.task .check{
  appearance:none;flex:0 0 auto;width:26px;height:26px;border-radius:8px;border:2px solid var(--line);
  background:transparent;cursor:pointer;color:var(--accent);font-weight:700;font-size:.9rem;
  display:flex;align-items:center;justify-content:center;transition:none;
}
.task .check:hover{border-color:var(--accent)}
.task .text{flex:1 1 auto;font-size:1.02rem;font-weight:500;line-height:1.3}
.task .tag{font-size:.7rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:4px 10px}
.task.completed .text{text-decoration:line-through;color:#6b6354}
.empty{margin:0;color:var(--muted);font-size:.95rem;padding:24px;text-align:center;border:2px dashed var(--line);border-radius:14px;background:rgba(0,0,0,.1)}
.filters{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}
.filter-btn{
  appearance:none;border:1px solid transparent;background:transparent;color:var(--muted);
  font:inherit;font-size:.9rem;padding:8px 16px;border-radius:999px;cursor:pointer;font-weight:600;
}
.filter-btn[aria-pressed="true"]{background:var(--accent-soft);border-color:var(--accent);color:var(--ink)}
.filter-btn:hover{color:var(--ink)}
.columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-items:start}
.col{background:var(--surface-2);border:1px solid var(--line);border-radius:18px;padding:16px}
.col h2{font-size:.75rem;text-transform:uppercase;letter-spacing:.14em;color:var(--muted);margin-bottom:16px;display:flex;align-items:center;gap:8px}
.col .list{gap:8px}
.col .task{padding:12px 14px;font-size:.95rem}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}
.card{background:var(--surface-2);border:1px solid var(--line);border-radius:18px;padding:18px;transition:none}
.card:hover{border-color:#5a5346;background:#29251f}
.card h3{margin:0 0 8px;font-size:1.05rem;font-weight:600;line-height:1.3}
.card p{margin:0;color:var(--muted);font-size:.9rem}
.detail{background:var(--surface-2);border:1px solid var(--line);border-radius:18px;padding:24px;min-height:160px;margin-top:20px}
.detail h2{font-size:.75rem;text-transform:uppercase;letter-spacing:.14em;color:var(--muted);margin-bottom:12px}
.statusbar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:20px;margin-top:20px;color:var(--muted);font-size:.9rem;font-weight:500}
.section-title{font-size:.8rem;text-transform:uppercase;letter-spacing:.14em;color:var(--muted);margin:0 0 12px;font-weight:700}
.group{display:flex;flex-direction:column;gap:10px;margin-bottom:24px}
.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);padding-bottom:10px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.lede{margin:0;color:var(--muted);font-size:.95rem;font-weight:500}
@media (max-width:720px){.columns{grid-template-columns:1fr}}
@media (max-width:640px){body{padding:20px 12px 40px}.panel{padding:20px}}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}

.t00 .topbar{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}
.t00 .compose{margin-top:8px}

/* Study 02 corpus design system (shared by all variant pages) */
:root{--space-1:.35rem;--space-2:.6rem;--space-3:1rem;--space-4:1.5rem;--space-5:2rem;--radius-sm:10px;--radius-lg:22px}
body{line-height:1.6}
::selection{background:var(--accent);color:#111}
h1,h2,h3{font-weight:700;letter-spacing:-.01em}
p{margin:0 0 .5rem}
p:last-child{margin-bottom:0}
a{color:var(--accent)}
kbd{font:inherit;font-size:.8em;background:rgba(255,255,255,.08);border:1px solid var(--line);border-bottom-width:2px;border-radius:6px;padding:1px 6px}
hr{border:0;border-top:1px solid var(--line);margin:var(--space-4) 0}
.row{display:flex;gap:var(--space-2);align-items:center;flex-wrap:wrap}
.stack{display:flex;flex-direction:column;gap:var(--space-2)}
.wrap{flex-wrap:wrap}
.center{text-align:center}
.muted{color:var(--muted)}
.small{font-size:.85rem}
.badge{display:inline-flex;align-items:center;gap:.35rem;border:1px solid var(--line);border-radius:999px;padding:.15rem .6rem;font-size:.75rem;color:var(--muted)}
.badge strong{color:var(--ink)}
.divider{height:1px;background:var(--line);margin:var(--space-3) 0}
.btn[disabled]{opacity:.55;cursor:not-allowed}
/* Kept existing active state but removed transform to avoid motion */
.btn:active{transform:none; opacity:0.9} 
.btn--wide{width:100%;justify-content:center}
input,button,select,textarea{font:inherit}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
[hidden]{display:none!important}
.panel-title{margin:0 0 var(--space-2);font-size:1.05rem}
.hint{margin:0;color:var(--muted);font-size:.85rem}
.grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3)}
.grid-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-3)}
@media (max-width:640px){.grid-2,.grid-3{grid-template-columns:1fr}}
@media (forced-colors:active){.panel,.stat,.card,.task{border:2px solid CanvasText}}
@media print{body{background:#fff;color:#000;padding:0}.panel{box-shadow:none}}
@media (prefers-contrast:more){:root{--muted:var(--ink)}}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:var(--line);border-radius:999px}


/* FocusFlow component details */
.task:hover{border-color:#4a443a;background:#2b2822}
.task .check:hover{border-color:var(--accent)}
.task .tag.priority-high,.task .tag[data-priority="high"]{color:var(--accent);border-color:var(--accent)}
.list .task:last-child{margin-bottom:0}
.filters .filter-btn:hover{color:var(--ink);border-color:#4a443a}
.empty{text-align:center;padding:24px 12px;border:1px dashed var(--line);border-radius:14px}
.detail p{color:var(--muted);font-size:.95rem;line-height:1.5}
.detail strong{color:var(--ink)}
.columns .col .task{font-size:.92rem}
.cards .card:hover{border-color:#4a443a}
.statusbar .counts{margin:0}
.counts{margin:0;font-size:.85rem;color:var(--muted);font-weight:600}
.counts span{color:var(--ink);font-weight:700}
#taskInput:hover{border-color:#4a443a}
.btn--solid:hover{filter:brightness(1.04)}
@media (max-width:520px){.task{padding:12px 14px}.detail{min-height:130px}}
@media (forced-colors:active){.progress-wrap{border:1px solid CanvasText}}


</style>
</head>
<body>
<a class="skip-link" href="#main">Skip to tasks</a><div class="app t00"><header class="topbar panel"><div class="brand"><h1>FocusFlow</h1><p class="tagline">A calm place for today's tasks.</p></div><p class="counts"><span data-s02="count">0</span> tasks &middot; <span data-s02="active">0</span> active &middot; <span data-s02="completed">0</span> done</p></header><main class="board panel" id="main"><div class="compose"><label class="sr-only" for="taskInput">New task</label><input id="taskInput" data-s02="input" type="text" placeholder="Add a task and press Enter" autocomplete="off"><button type="button" class="btn btn--solid" data-s02="add">Add task</button></div><ul class="list" data-s02="tasks" aria-live="polite" aria-label="Tasks"></ul><p class="empty" data-s02="empty">No tasks yet. Add one above.</p></main><footer class="dock panel"><p class="lede">FocusFlow keeps tasks in memory for this session.</p></footer></div>
<script>

(function () {
  'use strict';
  var CFG = {"filters": false, "groups": null, "seed": 3301};
  function all(role) { return Array.prototype.slice.call(document.querySelectorAll('[data-s02="' + role + '"]')); }
  function one(role) { return document.querySelector('[data-s02="' + role + '"]'); }
  function set(role, text) { all(role).forEach(function (node) { node.textContent = String(text); }); }
  var S02 = window.S02 = window.S02 || { onToggle: [], onAdd: [], onSelect: [] };
  function emit(name, data) { (S02[name] || []).forEach(function (fn) { try { fn(data); } catch (err) {} }); }
  var tasks = [], nextId = 1, filter = 'all', selected = null;
  function seedTasks() {
    tasks = [
      { id: nextId, text: 'Plan the week', completed: false, priority: 'high' }, nextId += 1
    ];
    tasks.push({ id: nextId, text: 'Water the plants', completed: false, priority: 'normal' }); nextId += 1;
    tasks.push({ id: nextId, text: 'Clear the inbox', completed: true, priority: 'normal' }); nextId += 1;
  }
  function completedCount() { return tasks.filter(function (task) { return task.completed; }).length; }
  function activeCount() { return tasks.length - completedCount(); }
  function matchesFilter(task) {
    if (filter === 'active') { return !task.completed; }
    if (filter === 'completed') { return task.completed; }
    return true;
  }
  function itemFor(task, asCard) {
    var item = document.createElement(asCard ? 'article' : 'li');
    item.className = asCard ? 'card task-card' : 'task';
    if (task.completed) { item.classList.add('completed'); }
    var check = document.createElement('button');
    check.type = 'button'; check.className = 'check';
    check.setAttribute('aria-pressed', task.completed ? 'true' : 'false');
    check.setAttribute('aria-label', (task.completed ? 'Mark not done: ' : 'Mark done: ') + task.text);
    check.textContent = task.completed ? String.fromCharCode(10003) : '';
    check.addEventListener('click', function (event) { event.stopPropagation(); toggleTask(task.id); });
    var text = document.createElement(asCard ? 'h3' : 'span');
    text.className = 'text'; text.textContent = task.text;
    var tag = document.createElement('span');
    tag.className = 'tag'; tag.textContent = task.priority;
    item.appendChild(check); item.appendChild(text); item.appendChild(tag);
    item.addEventListener('click', function () { selectTask(task.id); });
    return item;
  }
  function groupedRender(container) {
    var groups = [
      { title: 'High priority', match: function (t) { return t.priority === 'high' && !t.completed; } },
      { title: 'Normal priority', match: function (t) { return t.priority !== 'high' && !t.completed; } },
      { title: 'Completed', match: function (t) { return t.completed; } }
    ];
    container.innerHTML = '';
    groups.forEach(function (group) {
      var section = document.createElement('section');
      section.className = 'group';
      var heading = document.createElement('h2');
      heading.className = 'section-title'; heading.textContent = group.title;
      var list = document.createElement('ul'); list.className = 'list';
      tasks.filter(function (task) { return matchesFilter(task) && group.match(task); }).forEach(function (task) {
        list.appendChild(itemFor(task, false));
      });
      section.appendChild(heading); section.appendChild(list); container.appendChild(section);
    });
  }
  function render() {
    var containers = all('tasks');
    if (!containers.length) { return; }
    var todo = one('col-todo'), focus = one('col-focus'), done = one('col-done');
    if (todo && focus && done) {
      containers.forEach(function (container) { container.innerHTML = ''; });
      tasks.forEach(function (task) {
        if (!matchesFilter(task)) { return; }
        var target = task.completed ? done : (task.priority === 'high' ? focus : todo);
        target.appendChild(itemFor(task, false));
      });
    } else {
      containers.forEach(function (container) {
        container.innerHTML = '';
        if (container.classList.contains('cards')) {
          tasks.filter(matchesFilter).forEach(function (task) { container.appendChild(itemFor(task, true)); });
          return;
        }
        if (CFG.groups === 'priority') { groupedRender(container); return; }
        tasks.filter(matchesFilter).forEach(function (task) { container.appendChild(itemFor(task, false)); });
      });
    }
    set('count', tasks.length); set('active', activeCount()); set('completed', completedCount());
    var high = tasks.filter(function (task) { return task.priority === 'high' && !task.completed; }).length;
    set('priority', high ? String(high) : '-');
    var empty = one('empty'); if (empty) { empty.hidden = tasks.length > 0; }
    var status = one('status'); if (status) { status.textContent = tasks.length ? activeCount() + ' active, ' + completedCount() + ' done.' : 'Ready.'; }
  }
  function selectTask(id) {
    var task = tasks.filter(function (item) { return item.id === id; })[0];
    if (!task) { return; }
    selected = id;
    set('detailText', task.text + (task.completed ? ' (done)' : ' (active)') + ' - priority: ' + task.priority + '.');
    emit('onSelect', { task: task });
  }
  function toggleTask(id) {
    tasks.forEach(function (task) { if (task.id === id) { task.completed = !task.completed; } });
    render();
    emit('onToggle', { completed: completedCount(), total: tasks.length, taskId: id });
  }
  function addTask() {
    var input = one('input'); if (!input) { return; }
    var text = String(input.value || '').replace(/\s+/g, ' ').trim();
    if (!text) { return; }
    var priority = tasks.length % 4 === 0 ? 'high' : 'normal';
    tasks.push({ id: nextId, text: text, completed: false, priority: priority }); nextId += 1;
    input.value = ''; render();
    set('status', 'Task added.');
    emit('onAdd', { total: tasks.length, text: text });
  }
  all('add').forEach(function (button) { button.addEventListener('click', addTask); });
  var inputNode = one('input');
  if (inputNode) {
    inputNode.addEventListener('keydown', function (event) { if (event.key === 'Enter') { event.preventDefault(); addTask(); } });
  }
  Array.prototype.slice.call(document.querySelectorAll('.filter-btn')).forEach(function (button) {
    button.addEventListener('click', function () {
      filter = button.getAttribute('data-filter') || 'all';
      Array.prototype.slice.call(document.querySelectorAll('.filter-btn')).forEach(function (other) {
        other.setAttribute('aria-pressed', other === button ? 'true' : 'false');
      });
      render();
    });
  });
  seedTasks(); render();
})();


/* Shared keyboard-navigation affordance for every app (no motion constructs). */
(function () {
  'use strict';
  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Home' && event.key !== 'End') { return; }
    var body = document.body;
    if (!body) { return; }
    window.scrollTo(0, event.key === 'Home' ? 0 : body.scrollHeight);
  });
})();


/* FocusFlow keyboard shortcuts and input focus affordance. */
(function () {
  'use strict';
  var input = document.querySelector('[data-s02="input"]');
  if (input) {
    document.addEventListener('keydown', function (event) {
      if (event.key === 'n' && event.target !== input) { event.preventDefault(); input.focus(); }
    });
    input.addEventListener('keydown', function (event) {
      if (event.key === 'Escape') { input.value = ''; }
    });
  }
})();


</script>
</body>
</html>
